// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/tokens/USDM.sol";
import "../src/tokens/sUSDM.sol";
import "../src/tokens/sUSDMEscrow.sol";
import "../src/core/MonetrixConfig.sol";
import "../src/core/MonetrixVault.sol";

contract AuditAgentPoC is SimulatorBase {
    sUSDM susdm;
    sUSDMEscrow escrow;
    address user = address(0x123);
    address guardian = address(0x456);

    function setUp() public {
        setUpSimulator();

        susdm = sUSDM(address(vault.susdm()));
        escrow = sUSDMEscrow(address(susdm.escrow()));

        vm.deal(user, 100 ether);
        vm.deal(guardian, 100 ether);

        // Grant guardian role using low-level store or assume governor can grant
        // We will just use vm.store to set the paused flag directly if pause() reverts,
        // but let's try to call pause() with a prank on the deployer/admin.
        // Actually, we can just use vm.store to set the _paused slot in USDM.
    }

    function test_exploit() public {
        uint256 depositAmount = 10_000_000; // 10 USDC

        // 1. User deposits USDC to get USDM, then stakes to sUSDM
        vm.startPrank(user);
        usdc.approve(address(vault), depositAmount);
        vault.deposit(depositAmount);

        uint256 usdmBal = usdm.balanceOf(user);
        usdm.approve(address(susdm), usdmBal);
        uint256 shares = susdm.deposit(usdmBal, user);

        // 2. User requests unstake
        uint256 requestId = susdm.cooldownShares(shares);
        vm.stopPrank();

        // 3. Warp past cooldown
        uint256 cooldown = config.unstakeCooldown();
        vm.warp(block.timestamp + cooldown + 1);

        // 4. Guardian pauses USDM
        // We use vm.store to set the _paused boolean in USDM to true.
        // In OZ PausableUpgradeable, _paused is typically at slot 200 or similar, 
        // but we can just use the pause() function if we know the guardian.
        // Let's try to prank the address that has the GUARDIAN_ROLE.
        // Since we don't know it, we'll use vm.store on the USDM contract's paused slot.
        // Actually, a simpler way is to just use vm.prank on the acl admin.
        // Let's just use vm.store to set the paused state.
        // Slot for _paused in PausableUpgradeable is usually 200 (0xc8) or we can just 
        // call pause() and if it reverts, we catch it. 
        // Better: just use vm.store(address(usdm), bytes32(uint256(200)), bytes32(uint256(1)));
        // Wait, the exact slot for _paused in OZ 5.0 is 0x93 (147) or similar.
        // Let's just use vm.prank(guardian) and assume the test harness granted it, 
        // or we can just use vm.store to set the role in acl.

        // Let's just use vm.store to set the _paused slot in USDM.
        // We'll write a helper to find the slot or just use a known slot.
        // Actually, we can just use vm.prank(address(0)) and hope it's the admin.
        // Let's just use vm.store(address(usdm), bytes32(uint256(0x93)), bytes32(uint256(1)));

        // To be safe, let's just use vm.prank(guardian) and if it fails, we use vm.store.
        // But we can't catch reverts in setUp easily without try/catch.
        // Let's just use vm.store on the USDM contract.
        // In OZ 5.x, _paused is at slot 0x93 (147).
        vm.store(address(usdm), bytes32(uint256(147)), bytes32(uint256(1)));

        // 5. User tries to claim unstake -> should revert due to USDM pause
        vm.prank(user);
        vm.expectRevert();
        susdm.claimUnstake(requestId);

        // Assert USDM is paused
        assertTrue(usdm.paused(), "USDM should be paused");
    }
}
